import {BUNKER_LIGHTING as lighting} from './reference-lighting.js';
import * as THREE from './vendor/three.module.js';
import {AssetLibrary,cloneMaterial} from './assets.js';
import {REFERENCE_MAP as map} from './reference-map.js';
import {ReferenceLayout,ReferenceFlowField} from './reference-layout.js';
import {buildReferenceEnvironment} from './reference-environment.js';
import {drawReferencePlan} from './reference-plan.js';
const $=id=>document.getElementById(id),layout=new ReferenceLayout(map),flow=new ReferenceFlowField(layout),plan=$('plan'),ctx=plan.getContext('2d');let environment,route=[],eye=false,azimuth=.65,elevation=.9,distance=48,drag;
const renderer=new THREE.WebGLRenderer({canvas:$('scene'),antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.localClippingEnabled=true;
const scene=new THREE.Scene();scene.background=new THREE.Color('#203547');scene.add(new THREE.HemisphereLight(lighting.sky,lighting.ground,lighting.ambient));const sun=new THREE.DirectionalLight('#abc6ed',1.4);sun.position.set(-30,65,25);scene.add(sun);const fill=new THREE.DirectionalLight(lighting.fill,lighting.fillIntensity);fill.position.set(45,25,-40);scene.add(fill);const root=new THREE.Group();scene.add(root);const camera=new THREE.PerspectiveCamera(75,1,.05,200),plane=new THREE.Plane(new THREE.Vector3(0,-1,0),2),target=new THREE.Vector3(9,1,-1),wire=new THREE.Group();scene.add(wire);
function level(){return Number($('floor').value)}
function draw(){drawReferencePlan(ctx,map,25,25,plan.width-50,plan.height-50,{level:level(),navigation:$('nav').checked,stations:$('anchors').checked,checkpoints:true,route,layout});if(!eye){plane.constant=level()+2;camera.position.set(target.x+Math.sin(azimuth)*Math.cos(elevation)*distance,target.y+Math.sin(elevation)*distance,target.z+Math.cos(azimuth)*Math.cos(elevation)*distance);camera.lookAt(target)}for(const gate of environment?.gateMeshes.values()||[])gate.group.visible=!layout.unlocked[gate.data.unlock];wire.visible=$('wire').checked;renderer.render(scene,camera)}
function resize(){const canvas=$('scene'),w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();draw()}
for(const id of ['floor','nav','anchors','wire'])$(id).onchange=()=>{route=[];eye=false;$('view-name').textContent='FusionFall / cutaway';draw()};
$('open').onchange=()=>{for(const gate of map.gates)layout.unlocked[gate.unlock]=$('open').checked;layout.refresh();route=[];draw()};
for(const [i,p]of map.checkpoints.entries()){const button=document.createElement('button');button.textContent=(i+1)+'. '+p.name;button.onclick=()=>{eye=true;plane.constant=100;camera.position.fromArray(p.position);camera.lookAt(...p.target);$('view-name').textContent=p.name+' / eye level';draw()};$('cameras').appendChild(button)}
$('overview').onclick=()=>{eye=false;$('view-name').textContent='FusionFall / cutaway';draw()};
plan.onclick=event=>{const rect=plan.getBoundingClientRect(),px=(event.clientX-rect.left)*plan.width/rect.width,pz=(event.clientY-rect.top)*plan.height/rect.height,b=map.bounds,point={x:b.minX+(px-25)/(plan.width-50)*(b.maxX-b.minX),z:b.minZ+(pz-25)/(plan.height-50)*(b.maxZ-b.minZ),floorY:level()};flow.update(point);let id=flow.index(map.start.x,map.start.z,0);route=[];let length=0;if(flow.field[id]<0){$('route-status').textContent='Closed barriers separate this destination from spawn.';draw();return}for(let step=0;step<flow.nodes.length;step++){const p=flow.nodes[id];route.push(p);if(flow.field[id]===0)break;const next=flow.links[id].find(n=>flow.field[n]>=0&&flow.field[n]<flow.field[id]);if(next===undefined)break;const q=flow.nodes[next];length+=Math.hypot(q.x-p.x,q.z-p.z,q.y-p.y);id=next}$('route-status').textContent=`${length.toFixed(1)} m source route · ${(length/5.25).toFixed(1)} s walking · ${route.some(p=>p.y>2)?'uses upper floor':'lower floor'}`;draw()};
$('scene').onpointerdown=e=>{drag=[e.clientX,e.clientY];$('scene').setPointerCapture(e.pointerId)};$('scene').onpointerup=()=>drag=null;$('scene').onpointermove=e=>{if(!drag||eye)return;azimuth-=(e.clientX-drag[0])*.008;elevation=Math.max(.12,Math.min(1.5,elevation+(e.clientY-drag[1])*.006));drag=[e.clientX,e.clientY];draw()};$('scene').onwheel=e=>{e.preventDefault();distance=Math.max(12,Math.min(90,distance+e.deltaY*.025));draw()};window.addEventListener('resize',resize);
$('facts').textContent=`${map.reference.data.brushes.length} source brushes / ${map.reference.data.faces.length} faces / ${map.reference.data.nav.nodes.length} walking samples / 2 floors / 3 independent barriers / 0 relocated structural vertices`;
try{const assets=new AssetLibrary();await assets.load((value,text)=>$('loading').textContent=text);environment=buildReferenceEnvironment(root,assets,null,map);root.traverse(o=>{if(!o.isMesh)return;o.material=Array.isArray(o.material)?o.material.map(cloneMaterial):cloneMaterial(o.material);for(const m of Array.isArray(o.material)?o.material:[o.material])m.clippingPlanes=[plane]});for(const part of environment.original.children){if(!part.isMesh)continue;const lines=new THREE.LineSegments(new THREE.EdgesGeometry(part.geometry,25),new THREE.LineBasicMaterial({color:'#ed8eff',transparent:true,opacity:.35,clippingPlanes:[plane]}));wire.add(lines)}$('loading').hidden=true;resize()}catch(error){$('loading').textContent=error.message}
